//
// The fixed half of a preview: it reads the outcomes a docs page states, and
// prints what Render.swift decides from them. Only the docs site builds this
// file; the app never carries it.

import Foundation

/// What one poll of one watch returned, as a docs page writes it.
struct Sample: Decodable {
    var code: Int?
    var out: String?
    var err: String?
    var status: Int?
    var exists: Bool?
    var installed: Bool?
    var loaded: Bool?
    var running: Bool?
    var enabled: Bool?
    var pid: Int?
}

struct SampleState: Decodable {
    var name: String
    var watches: [String: Sample]
}

extension RunOutcome {
    init(sample: Sample) {
        let code = sample.code ?? 0
        self.init(ok: code == 0, code: code, out: sample.out ?? "", err: sample.err ?? "")
    }
}

extension LaunchAgentOutcome {
    /// A page states the three flags it wants to draw. Anything it leaves out
    /// follows: a running agent is loaded, and nothing runs uninstalled unless
    /// the page says so outright.
    init(sample: Sample, label: String, plist: String) {
        let running = sample.running ?? false
        self.init(
            installed: sample.installed ?? true,
            loaded: sample.loaded ?? running,
            running: running,
            enabled: sample.enabled ?? true,
            pid: sample.pid ?? (running ? 1 : 0),
            label: label,
            plist: Launchd.expand(plist)
        )
    }
}

extension HTTPOutcome {
    init(sample: Sample) {
        let status = sample.status ?? 200
        self.init(ok: (200..<300).contains(status), status: status, out: sample.out ?? "")
    }
}

func readStates() -> [SampleState] {
    let data = FileHandle.standardInput.readDataToEndOfFile()
    do {
        return try JSONDecoder().decode([SampleState].self, from: data)
    } catch {
        FileHandle.standardError.write(Data("preview: unreadable states: \(error)\n".utf8))
        exit(1)
    }
}

func frame(_ state: String, _ face: Face, _ menu: [MenuNode]) -> [String: Any] {
    ["state": state, "face": encoded(face), "menu": menu.map { encoded($0) }]
}

private func encoded(_ icon: MenuIcon) -> [String: Any] {
    switch icon {
    case .symbol(let name): return ["symbol": name]
    case .asset(let name): return ["asset": name]
    case .colored(let name, let fg, let bg): return ["symbol": name, "fg": fg, "bg": bg]
    }
}

private func encoded(_ face: Face) -> [String: Any] {
    var out: [String: Any] = ["icon": encoded(face.icon), "dim": face.dim, "badge": face.badge]
    if let tint = face.tint {
        out["tint"] = ["color": tint.name, "alpha": tint.alpha, "style": tint.style.rawValue,
                       "size": tint.size.rawValue, "corner": tint.corner.rawValue, "wrap": tint.wrap.rawValue, "menu": tint.menu]
    }
    return out
}

private func encoded(_ action: MenuAction) -> [String: Any] {
    switch action {
    case .run(let argv): return ["run": argv]
    case .open(let target): return ["open": target]
    case .post(let url, let body): return ["post": ["url": url, "body": body]]
    case .agent(let label, _, let verb): return ["agent": ["label": label, "verb": verb.rawValue]]
    // A closure has nothing to render but the fact that it is one: what the
    // hand-written method does is not knowable from here.
    case .swift: return ["swift": true]
    case .window(let verb): return ["window": String(describing: verb)]
    case .quit: return ["quit": true]
    }
}

private func encoded(_ node: MenuNode) -> [String: Any] {
    var out: [String: Any]
    let look: Look
    switch node {
    case .separator:
        return ["separator": true]
    case .item(let title, let action, let l):
        out = ["title": title]
        if let action { out["action"] = encoded(action) }
        look = l
    case .toggle(let title, let on, let action, let l):
        out = ["title": title, "on": on, "action": encoded(action)]
        look = l
    case .submenu(let title, let items, let l):
        out = ["title": title, "items": items.map { encoded($0) }]
        look = l
    case .field(let placeholder, let make):
        return ["field": placeholder, "action": encoded(make("query"))]
    }
    if let icon = look.icon { out["icon"] = encoded(icon) }
    if look.size > 0 { out["size"] = min(look.size, Badges.maxSize) }
    if Look.weights[look.weight] != nil { out["weight"] = look.weight }
    let indent = Int(min(max(look.indent, 0), 15))
    if indent > 0 { out["indent"] = indent }
    if let enabled = look.enabled { out["enabled"] = enabled }
    if !look.subtitle.isEmpty { out["subtitle"] = look.subtitle }
    if let key = look.key { out["key"] = shortcut(key) }
    if look.header { out["header"] = true }
    // Dropped as the menu drops them, so the preview shows what a menu would.
    let shown = Badges.shown(look.badges)
    if !shown.isEmpty {
        out["badges"] = shown.map {
            ["text": $0.text, "symbol": $0.symbol, "fg": $0.fg, "bg": $0.bg, "at": $0.at == "start" ? "start" : "end",
             "plain": $0.plain]
        }
    }
    return out
}

/// A shortcut as a menu prints it: ⌃⌥⇧⌘ then the key.
private func shortcut(_ k: KeyCombo) -> String {
    var s = ""
    if k.modifiers.contains(.control) { s += "⌃" }
    if k.modifiers.contains(.option) { s += "⌥" }
    if k.modifiers.contains(.shift) { s += "⇧" }
    if k.modifiers.contains(.command) { s += "⌘" }
    let names: [String: String] = ["\r": "↩", "\t": "⇥", "\u{1b}": "⎋", "\u{8}": "⌫", "\u{7f}": "⌦", " ": "Space"]
    return s + (names[k.key] ?? (k.key.unicodeScalars.first.map { $0.value >= 0xF700 } == true ? "•" : k.key.uppercased()))
}

func emit(_ frames: [Any]) {
    guard let data = try? JSONSerialization.data(withJSONObject: frames, options: [.sortedKeys]) else {
        FileHandle.standardError.write(Data("preview: frames are not JSON\n".utf8))
        exit(1)
    }
    FileHandle.standardOutput.write(data)
}
